from uuid import UUID
from typing import Dict, List, Optional

from .models import Item, ItemCreate, ItemUpdate


class ItemStore:
    """In-memory store for items."""

    def __init__(self):
        self._items: Dict[UUID, Item] = {}

    def create(self, item_data: ItemCreate) -> Item:
        """Create a new item."""
        item = Item(name=item_data.name, description=item_data.description)
        self._items[item.id] = item
        return item

    def get(self, item_id: UUID) -> Optional[Item]:
        """Get an item by ID."""
        return self._items.get(item_id)

    def get_all(self) -> List[Item]:
        """Get all items."""
        return list(self._items.values())

    def update(self, item_id: UUID, item_data: ItemUpdate) -> Optional[Item]:
